import { useEffect, useState } from 'react'
import { tenantsService, type TenantSummary } from '@/integrations/supabase/tenants'
import { useTenant } from '@/app/providers/TenantProvider'
import { Building2, Plus, CheckCircle2, PauseCircle, Loader2 } from 'lucide-react'
import { toast } from 'sonner'

export function TenantsAdminPage() {
  const { activeSlug, setActiveSlug } = useTenant()
  const [tenants, setTenants] = useState<TenantSummary[]>([])
  const [loading, setLoading] = useState(true)
  const [showCreate, setShowCreate] = useState(false)
  const [newName, setNewName] = useState('')
  const [newSlug, setNewSlug] = useState('')
  const [creating, setCreating] = useState(false)

  const load = async () => {
    setLoading(true)
    const list = await tenantsService.listAll()
    setTenants(list)
    setLoading(false)
  }

  useEffect(() => { load() }, [])

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!newSlug || !newName) return
    setCreating(true)
    try {
      await tenantsService.create({ slug: newSlug.trim().toLowerCase(), name: newName.trim() })
      toast.success(`Tenant "${newName}" created with default workplace`)
      setNewName(''); setNewSlug(''); setShowCreate(false)
      load()
    } catch (err: any) {
      toast.error(err?.message ?? 'Failed to create tenant')
    } finally {
      setCreating(false)
    }
  }

  const handleSwitch = (slug: string) => {
    setActiveSlug(slug)
    toast.success(`Switched to ${slug}`)
  }

  const handleToggleStatus = async (t: TenantSummary) => {
    const next = t.status === 'suspended' ? 'active' : 'suspended'
    try {
      await tenantsService.updateStatus(t.id, next)
      toast.success(`${t.name} → ${next}`)
      load()
    } catch (err: any) {
      toast.error(err?.message ?? 'Failed to update status')
    }
  }

  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-4xl mx-auto">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h2 className="font-semibold mb-1">Tenants</h2>
            <p className="text-sm text-muted-foreground">Manage all tenants on this platform. Super-admin only.</p>
          </div>
          <button
            onClick={() => setShowCreate((v) => !v)}
            className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-primary text-primary-foreground text-sm font-medium hover:opacity-90"
          >
            <Plus size={14} /> New tenant
          </button>
        </div>

        {showCreate && (
          <form onSubmit={handleCreate} className="bg-surface rounded-xl border border-border p-4 mb-6 flex flex-col gap-3">
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="text-xs text-muted-foreground">Name</label>
                <input
                  value={newName}
                  onChange={(e) => setNewName(e.target.value)}
                  required
                  className="mt-1 w-full px-2 py-1.5 rounded-md border border-border bg-background text-sm"
                  placeholder="Acme Corp"
                />
              </div>
              <div>
                <label className="text-xs text-muted-foreground">Slug</label>
                <input
                  value={newSlug}
                  onChange={(e) => setNewSlug(e.target.value)}
                  required
                  pattern="[a-z0-9-]+"
                  className="mt-1 w-full px-2 py-1.5 rounded-md border border-border bg-background text-sm font-mono"
                  placeholder="acme"
                />
              </div>
            </div>
            <div className="flex gap-2">
              <button
                type="submit"
                disabled={creating}
                className="px-3 py-1.5 rounded-lg bg-accent text-accent-foreground text-sm font-medium disabled:opacity-50"
              >
                {creating ? 'Creating…' : 'Create'}
              </button>
              <button
                type="button"
                onClick={() => setShowCreate(false)}
                className="px-3 py-1.5 rounded-lg border border-border text-sm"
              >
                Cancel
              </button>
            </div>
          </form>
        )}

        <div className="bg-surface rounded-xl border border-border overflow-hidden">
          {loading ? (
            <div className="p-8 flex items-center justify-center text-muted-foreground">
              <Loader2 size={16} className="animate-spin mr-2" /> Loading tenants…
            </div>
          ) : tenants.length === 0 ? (
            <div className="p-8 text-center text-sm text-muted-foreground">
              No tenants yet. Create your first tenant above.
            </div>
          ) : (
            <ul className="divide-y divide-border">
              {tenants.map((t) => {
                const isActive = t.slug === activeSlug
                return (
                  <li key={t.id} className="p-4 flex items-center gap-4">
                    <div className="h-9 w-9 rounded-lg bg-muted flex items-center justify-center">
                      <Building2 size={16} className="text-muted-foreground" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <p className="font-medium text-sm truncate">{t.name}</p>
                        {isActive && (
                          <span className="text-[10px] px-1.5 py-0.5 rounded bg-accent/15 text-accent font-medium uppercase">Active</span>
                        )}
                        <span className={`text-[10px] px-1.5 py-0.5 rounded font-medium uppercase ${
                          t.status === 'suspended' ? 'bg-danger/15 text-danger' : 'bg-success/15 text-success'
                        }`}>
                          {t.status ?? 'active'}
                        </span>
                      </div>
                      <p className="text-xs text-muted-foreground font-mono">{t.slug}</p>
                    </div>
                    <div className="flex items-center gap-2">
                      <button
                        onClick={() => handleSwitch(t.slug)}
                        disabled={isActive}
                        className="text-xs px-2.5 py-1 rounded border border-border hover:bg-muted disabled:opacity-40"
                      >
                        {isActive ? 'In use' : 'Switch to'}
                      </button>
                      <button
                        onClick={() => handleToggleStatus(t)}
                        className="text-xs px-2.5 py-1 rounded border border-border hover:bg-muted inline-flex items-center gap-1"
                      >
                        {t.status === 'suspended' ? <><CheckCircle2 size={12}/> Activate</> : <><PauseCircle size={12}/> Suspend</>}
                      </button>
                    </div>
                  </li>
                )
              })}
            </ul>
          )}
        </div>

        <p className="text-xs text-muted-foreground mt-4">
          Switching tenant stores the slug in <code className="font-mono">localStorage.activeTenantSlug</code> and reloads the manifest. Clear it to fall back to <code className="font-mono">VITE_TENANT_SLUG</code>.
        </p>
      </div>
    </div>
  )
}
